class Solution {
public:
    bool wordPattern(string pattern, string s) {
        vector<string> words;
        string cur;
        for (char c : s) {
            if (c == ' ') {
                words.push_back(cur);
                cur.clear();
            } else {
                cur.push_back(c);
            }
        }
        words.push_back(cur);
        if (words.size() != pattern.size()) return false;
        map<char, string> pw;
        map<string, char> wp;
        for (int i = 0; i < (int)pattern.size(); i++) {
            char p = pattern[i];
            string& w = words[i];
            if (pw.count(p) && pw[p] != w) return false;
            if (wp.count(w) && wp[w] != p) return false;
            pw[p] = w;
            wp[w] = p;
        }
        return true;
    }
};
